3. import { LocalStorage } from "@microsoft/teams.common";
4. import config from "./config";
5. import { ManagedIdentityCredential } from "@azure/identity";
6. 
7. // Create storage for conversation history
8. const storage = new LocalStorage();
9. 
10. const createTokenFactory = () => {
11.   return async (scope: string | string[], tenantId?: string): Promise<string> => {
12.     const managedIdentityCredential = new ManagedIdentityCredential({
13.       clientId: process.env.CLIENT_ID,
14.     });
15.     const scopes = Array.isArray(scope) ? scope : [scope];
16.     const tokenResponse = await managedIdentityCredential.getToken(scopes, {
17.       tenantId: tenantId,
18.     });
19. 
20.     return tokenResponse.token;
21.   };
22. };
23. 
24. // Configure authentication using TokenCredentials
25. const tokenCredentials: TokenCredentials = {
26.   clientId: process.env.CLIENT_ID || "",
27.   token: createTokenFactory(),
28. };
29. 
30. const credentialOptions =
31.   config.MicrosoftAppType === "UserAssignedMsi" ? { ...tokenCredentials } : undefined;
32. 
33. // Create the app with storage
34. const app = new App({
35.   ...credentialOptions,
36.   storage,
37.   skipAuth: !process.env.CLIENT_ID,
38. });
39. 
40. // Interface for conversation state
41. interface ConversationState {
42.   count: number;
43. }
44. 
45. const getConversationState = (conversationId: string): ConversationState => {
46.   let state = storage.get(conversationId);
47.   if (!state) {
48.     state = { count: 0 };
49.     storage.set(conversationId, state);
50.   }
51.   return state;
52. };
53. 
54. app.on("message", async (context) => {
55.   const activity = context.activity;
56.   const text: string = stripMentionsText(activity);
57. 
58.   if (text === "/reset") {
59.     storage.delete(activity.conversation.id);
60.     await context.send("Ok I've deleted the current conversation state.");
61.     return;
62.   }
63. 
64.   if (text === "/count") {
65.     const state = getConversationState(activity.conversation.id);
66.     await context.send(`The count is ${state.count}`);
67.     return;
68.   }
69. 
70.   if (text === "/diag") {
71.     await context.send(JSON.stringify(activity));
72.     return;
73.   }
74. 
75.   if (text === "/state") {
76.     const state = getConversationState(activity.conversation.id);
77.     await context.send(JSON.stringify(state));
78.     return;
79.   }
80. 
81.   if (text === "/runtime") {
82.     const runtime = {
83.       nodeversion: process.version,
84.       sdkversion: "2.0.0", // Microsoft Teams SDK
85.     };
86.     await context.send(JSON.stringify(runtime));
87.     return;
88.   }
89. 
90.   // Default echo behavior
91.   const state = getConversationState(activity.conversation.id);
92.   state.count++;
