1. import { ManagedIdentityCredential } from "@azure/identity";
2. import { cardAttachment, TokenCredentials } from "@microsoft/teams.api";
3. import { App } from "@microsoft/teams.apps";
4. import { IAdaptiveCard } from "@microsoft/teams.cards";
5. import { ConsoleLogger } from "@microsoft/teams.common/logging";
6. import { DevtoolsPlugin } from "@microsoft/teams.dev";
7. 
8. import {
9.   createCard,
10.   createConversationMembersCard,
11.   createDummyCards,
12.   createLinkUnfurlCard,
13.   createMessageDetailsCard,
14. } from "./card";
15. 
16. const createTokenFactory = () => {
17.   return async (scope: string | string[], tenantId?: string): Promise<string> => {
18.     const managedIdentityCredential = new ManagedIdentityCredential({
19.       clientId: process.env.CLIENT_ID,
20.     });
21.     const scopes = Array.isArray(scope) ? scope : [scope];
22.     const tokenResponse = await managedIdentityCredential.getToken(scopes, {
23.       tenantId: tenantId,
24.     });
25. 
26.     return tokenResponse.token;
27.   };
28. };
29. 
30. // Configure authentication using TokenCredentials
31. const tokenCredentials: TokenCredentials = {
32.   clientId: process.env.CLIENT_ID || "",
33.   token: createTokenFactory(),
34. };
35. 
36. // Use managed identity in cloud environment, otherwise use devtools plugin for local development
37. const options =
38.   process.env.BOT_TYPE === "UserAssignedMsi"
39.     ? { ...tokenCredentials }
40.     : { plugins: [new DevtoolsPlugin()] };
41. 
42. const app = new App({
43.   ...options,
44.   logger: new ConsoleLogger("my-message-extension", { level: "debug" }),
45.   skipAuth: !process.env.CLIENT_ID,
46. });
47. 
48. app.on("install.add", async ({ send }) => {
49.   const greeting = `
50.   Hi this app handles:<br>
51.     1. Basic message handling - echoing back what you say<br>
52.     2. Link unfurling - creating preview cards when you paste URLs<br>
53.     3. Message extension commands - handling card creation.
54.   `;
55.   await send(greeting);
56. });
57. 
58. app.on("message", async ({ send, activity }) => {
59.   await send({ type: "typing" });
60.   await send(`you said "${activity.text}"`);
61. });
62. 
63. // :snippet-start: message-ext-query-link
64. app.on("message.ext.query-link", async ({ activity }) => {
65.   const { url } = activity.value;
66. 
67.   if (!url) {
68.     return { status: 400 };
69.   }
70. 
71.   const { card, thumbnail } = createLinkUnfurlCard(url);
72.   const attachment = {
73.     ...cardAttachment("adaptive", card), // expanded card in the compose box...
74.     preview: cardAttachment("thumbnail", thumbnail), //preview card in the compose box...
75.   };
76. 
77.   return {
78.     composeExtension: {
79.       type: "result",
80.       attachmentLayout: "list",
81.       attachments: [attachment],
82.     },
83.   };
84. });
85. // :snippet-end: message-ext-query-link
86. // :snippet-start: message-ext-submit
87. app.on("message.ext.submit", async ({ activity }) => {
88.   const { commandId } = activity.value;
89.   let card: IAdaptiveCard;
90. 
91.   if (commandId === "createCard") {
92.     // activity.value.commandContext == "compose"
93.     card = createCard(activity.value.data);
94.   } else if (commandId === "getMessageDetails" && activity.value.messagePayload) {
95.     // activity.value.commandContext == "message"
96.     card = createMessageDetailsCard(activity.value.messagePayload);
97.   } else {
98.     throw new Error(`Unknown commandId: ${commandId}`);
99.   }
100. 
101.   return {
102.     composeExtension: {
103.       type: "result",
104.       attachmentLayout: "list",
105.       attachments: [cardAttachment("adaptive", card)],
106.     },
107.   };
108. });
109. // :snippet-end: message-ext-submit
110. 
111. // :snippet-start: message-ext-open
112. app.on("message.ext.open", async ({ activity, api }) => {
113.   const conversationId = activity.conversation.id;
114.   const members = await api.conversations.members(conversationId).get();
115.   const card = createConversationMembersCard(members);
116. 
117.   return {
118.     task: {
119.       type: "continue",
120.       value: {
121.         title: "Conversation members",
122.         height: "small",
123.         width: "small",
124.         card: cardAttachment("adaptive", card),
125.       },
126.     },
127.   };
128. });
129. // :snippet-end: message-ext-open
130. 
131. // :snippet-start: message-ext-query
132. app.on("message.ext.query", async ({ activity }) => {
133.   const { commandId } = activity.value;
134.   const searchQuery = activity.value.parameters![0].value;
135. 
136.   if (commandId == "searchQuery") {
137.     const cards = await createDummyCards(searchQuery);
138.     const attachments = cards.map(({ card, thumbnail }) => {
139.       return {
140.         ...cardAttachment("adaptive", card), // expanded card in the compose box...
141.         preview: cardAttachment("thumbnail", thumbnail), // preview card in the compose box...
142.       };
143.     });
144. 
145.     return {
146.       composeExtension: {
147.         type: "result",
148.         attachmentLayout: "list",
149.         attachments: attachments,
150.       },
151.     };
152.   }
153. 
154.   return { status: 400 };
155. });
156. // :snippet-end: message-ext-query
157. 
158. (async () => {
159.   await app.start();
160. })();
161.

