   const greeting = `
   Hi this app handles:<br>
     1. Basic message handling - echoing back what you say<br>
     2. Link unfurling - creating preview cards when you paste URLs<br>
     3. Message extension commands - handling card creation.
   `;
   await send(greeting);
 });

